import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Handl SDK Generator — TypeScript Declaration (.d.ts) Backend","description":"","frontmatter":{"title":"Handl SDK Generator — TypeScript Declaration (.d.ts) Backend","type":"adr","date":"2026-10-28T00:00:00.000Z","status":"proposed","status_note":"Proposed."},"headers":[],"relativePath":"web/project/adrs/0115-handl-sdkgen-dts-js.md","filePath":"vendored/web/project/adrs/0115-handl-sdkgen-dts-js.md"}`),a={name:`web/project/adrs/0115-handl-sdkgen-dts-js.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0115-handl-sdk-generator-—-typescript-declaration-d-ts-backend" tabindex="-1">ADR-0115: Handl SDK Generator — TypeScript Declaration (.d.ts) Backend <a class="header-anchor" href="#adr-0115-handl-sdk-generator-—-typescript-declaration-d-ts-backend" aria-label="Permalink to “ADR-0115: Handl SDK Generator — TypeScript Declaration (.d.ts) Backend”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong>Example: using an NPM package from Handl.</strong> A function-oriented package like <code>express</code> ships <code>.d.ts</code> declarations. Running <code>hnl sdkgen dts</code> over them produces a port and a <code>js</code> adapter, and the resulting Handl source looks like any other imported module:</li><li><strong>Function libraries vs. component frameworks.</strong> This works well for function/value-oriented packages: Express, Lodash, Axios, <code>fs</code>, <code>crypto</code>, etc.</li><li><strong>Scope and limitations.</strong> The first version targets the subset of <code>.d.ts</code> that is sufficient for NPM libraries and server frameworks: modules, namespaces, interfaces, type aliases, function and method declarations, constants, enums, and callback types.</li><li><strong>Parser choice.</strong> The backend wraps a <code>.d.ts</code> parser behind the <code>SdkgenBackend</code> trait. The first implementation candidate is a Rust-based TypeScript parser (e.g. <code>swc</code>, <code>oxc_parser</code>, or <code>tree-sitter-typescript</code>). The parser crate is a private dependency of <code>plugin-sdkgen-backend-dts</code>; changing it does not affect the public <code>SdkgenBackend</code> API or the emitted Handl source. A parser evaluation and selection step is part of Phase 0.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p><a href="./0107-handl-sdk-generator.html">ADR-0107 — Handl SDK Generator</a> established a backend-agnostic <code>SdkgenModule</code> IR and a port-adapter emitter. The C backend (<code>plugin-sdkgen-backend-c</code>) is implemented, and the WebIDL/JS backend (<a href="./0113-handl-sdkgen-webidl-js.html">ADR-0113</a>) is the next high-priority target for Web platform APIs.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li>none recorded — legacy record; the design doc lists what was deferred.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>The large JavaScript ecosystem becomes reachable from Handl without manual</li><li>Component ergonomics (<code>.hfc</code> and <code>view</code> syntax) are handled separately by</li><li><code>.d.ts</code> is richer and more heterogeneous than WebIDL or C headers; the backend</li><li>Structural typing and advanced TS features do not map one-to-one to Handl&#39;s</li><li>The WebIDL and <code>.d.ts</code> backends share the same <code>js</code> client package and adapter</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>plugin-sdkgen-backend-dts</code> — where this is true.</li><li><code>plugin-sdkgen-backend-c</code> — where this is true.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>The full record (mechanism, tables, proofs, trade-offs): <a href="./../design/0115-handl-sdkgen-dts-js.html"><code>design/0115-handl-sdkgen-dts-js.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};